N.append({
 "id": 3, "lang": "Avestan",
 "words": "sâ 2, sâna, sya 1; fra-sanam",
 "verdict": "plausible",
 "derivation": "The forms are Pokorny's, and Nourai's page reference is exact: IEW p.920 s.v. skei- reads 'av. fra-sānəm \"Zerstörung\", sā-, sya- \"wehren\"'. Bartholomae has 'j. fra-sāna- n. Zerstörung, Vernichtung' (Yt 19.44) and the compound frakərəstō.fra-sāna- 'Zerstörung hervorrufend', so fra-sanam is real. But Nourai's gloss 'to sharpen ?' is not Pokorny's: Pokorny glosses the verb 'wehren' (to ward off), and his question-mark comes from Nourai himself, who in the chart's NOTE tells the reader to 'compare with the Avestan words from root Ak' — i.e. he suspects the sharpening sense belongs to the *h₂eḱ-/*ḱeh₂- family. Modern work goes further: Cheung 2007 (s.v. *saH 'to whet, cut') writes 'OAv. si- (sā-) to sharpen, cut ?. The verbal root may be non-existent. The attested forms can be interpreted differently: siiōdūm (< *siazd), sazdūm (< *saHh), v. Lubotsky 2001: 34', and he assigns what is left to PIE *ḱeh₂s- 'to sharpen, whet' (Pok. 541 f.), not to *skei-/*sek-. So the box is a faithful copy of Pokorny but rests on a reading modern Iranists no longer accept.",
 "derivation_fa": "صورت‌های این جعبه از پوکورنی گرفته شده و ارجاع نورایی دقیق است: پوکورنی در ص ۹۲۰ ذیل *skei- می‌نویسد «اوستایی fra-sānəm «نابودی»، sā-, sya- «بازداشتن»». بارتولومه نیز fra-sāna- «ویرانی، نابودی» را دارد، پس این واژه واقعی است. اما معنای «تیز کردن؟» که نورایی می‌دهد از پوکورنی نیست (او wehren «دفع کردن» می‌آورد)؛ خودِ نورایی هم در یادداشت جعبه خواننده را به ریشهٔ «Ak» ارجاع می‌دهد. چونگ (۲۰۰۷) ذیل *saH «تیز کردن، بریدن» می‌نویسد که «شاید این ستاک اصلاً وجود نداشته باشد» و صورت‌های گاهانی را جور دیگری می‌خواند، و آنچه می‌ماند را به ریشهٔ هندواروپایی *ḱeh₂s- «تیز کردن» (پوکورنی ۵۴۱ به بعد) می‌بندد نه به *skei-. داوری: با احتیاط پذیرفتنی است — نقل از پوکورنی درست است ولی خوانش آن کهنه شده است.",
 "sources": [],
 "ref_check": [
   {"ref": "POK:919", "status": "supports", "note": "POK_03.txt leaf 157 (printed page 920, i.e. the page whose entry begins at the foot of 919): 'skei- schneiden, trennen, scheiden, Erweiterung von sek- … av. fra-sānəm \"Zerstörung\", sā-, sya- \"wehren\"'. The forms and numbering (sā 2, sya 1) are Bartholomae's."}
 ],
 "consulted": [
   {"src": "BRT", "where": "s.v. fra-sāna-, frakərəstō.fra-sāna-", "stance": "partial", "note": "BRT.txt: 'j. fra-sāna- n. Zerstörung, Vernichtung: ava apəməm gayehe *frasānəm uštānahe Yt 19.44'; 'j. frakərəstō.fra-sāna- Adj. Zerstörung, Vernichtung hervorrufend' — the noun is confirmed, but Bartholomae's verb sā- is 'wehren', not 'schärfen'."},
   {"src": "CHEUNG", "where": "p.325 f. s.v. *saH 'to whet, cut'", "stance": "contradicts", "note": "'OAv. sī- (sā-) to sharpen, cut ?. The verbal root may be non-existent. … «PIE *ḱeHs- to sharpen, whet = LIV: 319 f. | Pok.: 541 f.' — a different PIE root from *sek-/*skei-."},
   {"src": "AHD", "where": "s.v. sek- / kō-", "stance": "partial", "note": "Watkins lists no Iranian sharpening verb under sek-; the 'whet' family (cōs, catus, hone) sits under a separate root."}
 ]
